def grep(pattern, flags, files):
    flags = flags.split()
    flag_l = "-l" in flags
    flag_n = "-n" in flags
    flag_i = "-i" in flags
    flag_v = "-v" in flags
    flag_x = "-x" in flags
    multiple_files = len(files) > 1

    def matches(line):
        if flag_i:
            line = line.lower()
            pattern = pattern.lower()
        if flag_x:
            return line == pattern
        return pattern in line

    result = ""
    for filename in files:
        with open(filename) as f:
            lines = f.read().splitlines()

        if flag_l:
            if any(matches(line) != flag_v for line in lines):
                result += filename + "\n"
        else:
            for lineno, line in enumerate(lines, 1):
                if matches(line) != flag_v:
                    prefix = ""
                    if multiple_files:
                        prefix += filename + ":"
                    if flag_n:
                        prefix += str(lineno) + ":"
                    result += prefix + line + "\n"
    return result

